    json: {
      company_id: formatData.company_id,
      company_name: formatData.company_name,
      content: formatData.content,
      feedback: 'Maximum retry attempts reached. Please review manually.',
      loop_count: loopCount,
      force_proceed: true,
      section_type: 'executive_summary_introduction'
    }
  };
}

// Extract specific feedback for improvement
let specificFeedback = checkerResponse;
if (checkerResponse.includes('NEEDS_REVISION:')) {
  specificFeedback = checkerResponse.split('NEEDS_REVISION:')[1].trim();
}

return {
