let company_name = inputData.company_name;
let generated_content = inputData.generated_content;

// If the data is nested, try to extract it
if (!company_id && inputData.json) {
  company_id = inputData.json.company_id;
  company_name = inputData.json.company_name;
  generated_content = inputData.json.generated_content;
}

console.log(`Extracted data:`);
console.log(`- company_id: ${company_id}`);
console.log(`- company_name: ${company_name}`);
console.log(`- generated_content length: ${generated_content ? generated_content.length : 'missing'}`);

// Ensure all required fields are present
if (!company_id || !company_name || !generated_content) {
  console.error(`❌ Missing required fields for database save after extraction`);
  console.error(`Available data:`, inputData);

  // Try to get from the previous node data that should be available
  const nodeData = $node['Format Section 1 Output']?.json;
  if (nodeData) {
    console.log(`Attempting to use Format Section 1 Output data:`, nodeData);
    company_id = nodeData.company_id || company_id;
    company_name = nodeData.company_name || company_name;
